// PreToolUse hook: blocks Edit/Write on generated files and real .env files.
// Exit code 2 = block the tool call and send stderr back to Claude.
import { appendFileSync } from 'node:fs'
import { fileURLToPath } from 'node:url'

const log = fileURLToPath(new URL('./hook.log', import.meta.url))

const PROTECTED = [
  { pattern: /routeTree\.gen\.ts$/, reason: 'is generated by the TanStack Router Vite plugin' },
  { pattern: /(^|\/)backend\/generated\//, reason: 'is generated by Prisma (run prisma:generate)' },
  {
    pattern: /(^|\/)\.env(\.(?!example$)[^/]+)?$/,
    reason: 'may contain secrets (edit .env.example instead)',
  },
]

let input = ''
process.stdin.on('data', (chunk) => (input += chunk))
process.stdin.on('end', () => {
  appendFileSync(log, `${new Date().toISOString()} cwd=${process.cwd()} input=${input}\n`)
  const filePath = JSON.parse(input.trim()).tool_input?.file_path?.replaceAll('\\', '/')
  const match = filePath && PROTECTED.find(({ pattern }) => pattern.test(filePath))

  if (match) {
    console.error(`Blocked: ${filePath} ${match.reason}.`)
    process.exit(2)
  }
})
